public ListNode deleteNode(ListNode head, int position) {
    ListNode dummy = new ListNode(0, head);
    ListNode prev = dummy;
    for (int i = 0; i < position; i++) {
        prev = prev.next;
    }
    prev.next = prev.next.next;
    return dummy.next;
}

